package com.osrsge.plugin.model;

import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

public class OfferEventDeduperTest
{
    private final OfferEventDeduper deduper = new OfferEventDeduper();

    @Test
    public void repeatedIdenticalEventIsDuplicate()
    {
        assertFalse(deduper.isDuplicate(0, GrandExchangeOfferState.CANCELLED_SELL, 1, 145));
        assertTrue(deduper.isDuplicate(0, GrandExchangeOfferState.CANCELLED_SELL, 1, 145));
    }

    @Test
    public void progressChangeIsNotDuplicate()
    {
        assertFalse(deduper.isDuplicate(0, GrandExchangeOfferState.BUYING, 1, 145));
        assertFalse(deduper.isDuplicate(0, GrandExchangeOfferState.BUYING, 2, 290));
        assertFalse(deduper.isDuplicate(0, GrandExchangeOfferState.BOUGHT, 2, 290));
    }

    @Test
    public void slotsAreIndependent()
    {
        assertFalse(deduper.isDuplicate(0, GrandExchangeOfferState.BOUGHT, 1, 145));
        assertFalse(deduper.isDuplicate(1, GrandExchangeOfferState.BOUGHT, 1, 145));
    }

    @Test
    public void seedMarksReplayedStateAsDuplicate()
    {
        deduper.seed(2, GrandExchangeOfferState.BOUGHT, 5, 500);
        assertTrue(deduper.isDuplicate(2, GrandExchangeOfferState.BOUGHT, 5, 500));
        assertFalse(deduper.isDuplicate(2, GrandExchangeOfferState.EMPTY, 0, 0));
    }

    @Test
    public void clearSlotForgetsHistory()
    {
        assertFalse(deduper.isDuplicate(0, GrandExchangeOfferState.BOUGHT, 1, 145));
        deduper.clearSlot(0);
        assertFalse(deduper.isDuplicate(0, GrandExchangeOfferState.BOUGHT, 1, 145));
    }
}

package com.osrsge.plugin.model;

import org.junit.Before;
import org.junit.Test;

import java.util.List;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertNull;

public class FlipTrackerTest
{
    private static final int ITEM = 444; // gold ore, not tax-exempt

    private FlipTracker tracker;

    @Before
    public void setUp()
    {
        tracker = new FlipTracker();
    }

    @Test
    public void simpleFlipComputesTaxedProfit()
    {
        // User's real trade: buy 1 @145, sell 1 @145 -> tax 2, profit -2
        tracker.recordBuy(ITEM, 1, 145, 1000L);
        CompletedTrade trade = tracker.matchSell(ITEM, "Gold ore", 1, 145, 2000L);

        assertEquals(1, trade.getQuantity());
        assertEquals(145, trade.getBuyPrice());
        assertEquals(145, trade.getSellPrice());
        assertEquals(2, trade.getTax());
        assertEquals(-2, trade.getProfit());
        assertEquals(1000L, trade.getBuyTimestamp());
        assertEquals(2000L, trade.getSellTimestamp());
    }

    @Test
    public void sellSpansMultipleBuysFifo()
    {
        tracker.recordBuy(ITEM, 10, 100, 1000L);
        tracker.recordBuy(ITEM, 10, 120, 2000L);

        // sell 15 @150: consumes 10 @100 + 5 @120 = 1600 cost
        CompletedTrade trade = tracker.matchSell(ITEM, "Gold ore", 15, 150, 3000L);

        assertEquals(15, trade.getQuantity());
        // weighted avg buy: 1600/15 = 106 (floor)
        assertEquals(106, trade.getBuyPrice());
        // tax: 150/50=3 per item * 15 = 45
        assertEquals(45, trade.getTax());
        // profit: 150*15 - 45 - 1600 = 2250 - 45 - 1600 = 605
        assertEquals(605, trade.getProfit());
        // oldest buy's timestamp is the flip start
        assertEquals(1000L, trade.getBuyTimestamp());

        // 5 remain of the second buy
        assertEquals(5, tracker.unmatchedQuantity(ITEM));
    }

    @Test
    public void sellBeyondLedgerOnlyMatchesAvailable()
    {
        tracker.recordBuy(ITEM, 3, 100, 1000L);
        CompletedTrade trade = tracker.matchSell(ITEM, "Gold ore", 10, 150, 2000L);

        assertEquals(3, trade.getQuantity());
        assertEquals(0, tracker.unmatchedQuantity(ITEM));
    }

    @Test
    public void sellWithEmptyLedgerReturnsNull()
    {
        assertNull(tracker.matchSell(ITEM, "Gold ore", 5, 150, 2000L));
    }

    @Test
    public void ledgerSnapshotRoundTrip()
    {
        tracker.recordBuy(ITEM, 10, 100, 1000L);
        tracker.matchSell(ITEM, "Gold ore", 4, 150, 2000L);

        List<BuyEntry> snapshot = tracker.snapshot();
        assertEquals(1, snapshot.size());
        assertEquals(6, snapshot.get(0).getRemaining());

        FlipTracker restored = new FlipTracker();
        restored.restore(snapshot);
        assertEquals(6, restored.unmatchedQuantity(ITEM));
    }
}

package com.osrsge.plugin.model;

import org.junit.Test;

import static org.junit.Assert.assertEquals;

public class GeTaxTest
{
    @Test
    public void twoPercentRoundedDown()
    {
        // User's real trade: gold ore sold at 145 -> 2 gp tax
        assertEquals(2, GeTax.taxFor(444, 145));
        assertEquals(1, GeTax.taxFor(444, 50));
        assertEquals(20_000, GeTax.taxFor(444, 1_000_000));
    }

    @Test
    public void underFiftyGpIsFree()
    {
        assertEquals(0, GeTax.taxFor(444, 49));
        assertEquals(0, GeTax.taxFor(444, 1));
        assertEquals(0, GeTax.taxFor(444, 0));
    }

    @Test
    public void cappedAtFiveMillionPerItem()
    {
        assertEquals(5_000_000, GeTax.taxFor(444, 300_000_000));
    }

    @Test
    public void exemptItemsPayNothing()
    {
        assertEquals(0, GeTax.taxFor(GeTax.OLD_SCHOOL_BOND, 5_000_000));
        assertEquals(0, GeTax.taxFor(2347, 1_000)); // hammer
    }
}

package com.osrsge.plugin.model;

import org.junit.Test;

import java.util.Arrays;
import java.util.List;

import static org.junit.Assert.assertEquals;

public class TradeAggregatorTest
{
    private static CompletedTrade trade(int itemId, String name, int buy, int sell, int qty, long tax, long sellTs)
    {
        return CompletedTrade.builder()
            .itemId(itemId)
            .itemName(name)
            .buyPrice(buy)
            .sellPrice(sell)
            .quantity(qty)
            .tax(tax)
            .profit((long) (sell) * qty - tax - (long) buy * qty)
            .buyTimestamp(sellTs - 1000)
            .sellTimestamp(sellTs)
            .synced(false)
            .build();
    }

    @Test
    public void aggregatesPerItem()
    {
        // User's real session: two gold ore flips, -5 each
        List<CompletedTrade> trades = Arrays.asList(
            trade(444, "Gold ore", 145, 142, 1, 2, 1000L),
            trade(444, "Gold ore", 150, 147, 1, 2, 2000L));

        List<TradeAggregator.ItemStats> items = TradeAggregator.aggregate(trades, 0L);

        assertEquals(1, items.size());
        TradeAggregator.ItemStats gold = items.get(0);
        assertEquals("Gold ore", gold.getItemName());
        assertEquals(-10, gold.getTotalProfit());
        assertEquals(2, gold.getFlips());
        assertEquals(2, gold.getQuantity());
        assertEquals(4, gold.getTotalTax());
        assertEquals(-5, gold.getAvgProfitEach());
        // avg buy: (145+150)/2 = 147 (floor of 147.5 by total/qty: 295/2=147)
        assertEquals(147, gold.getAvgBuyPrice());
        assertEquals(144, gold.getAvgSellPrice()); // 289/2
        // ROI: -10 / 295 = -3.39%
        assertEquals(-3.39, gold.getRoi(), 0.01);
    }

    @Test
    public void cutoffFiltersOldTrades()
    {
        List<CompletedTrade> trades = Arrays.asList(
            trade(444, "Gold ore", 145, 142, 1, 2, 1000L),
            trade(444, "Gold ore", 150, 147, 1, 2, 5000L));

        List<TradeAggregator.ItemStats> items = TradeAggregator.aggregate(trades, 2000L);

        assertEquals(1, items.size());
        assertEquals(1, items.get(0).getFlips());
        assertEquals(-5, items.get(0).getTotalProfit());
    }

    @Test
    public void sortsByMostRecentSell()
    {
        List<CompletedTrade> trades = Arrays.asList(
            trade(444, "Gold ore", 145, 142, 1, 2, 1000L),
            trade(2, "Cannonball", 180, 190, 100, 300, 9000L));

        List<TradeAggregator.ItemStats> items = TradeAggregator.aggregate(trades, 0L);

        assertEquals(2, items.size());
        assertEquals("Cannonball", items.get(0).getItemName());
        assertEquals("Gold ore", items.get(1).getItemName());
    }

    @Test
    public void totalsAcrossItems()
    {
        List<CompletedTrade> trades = Arrays.asList(
            trade(444, "Gold ore", 145, 142, 1, 2, 1000L),
            trade(2, "Cannonball", 180, 190, 100, 300, 9000L));

        TradeAggregator.Totals totals = TradeAggregator.totals(trades, 0L);

        // cannonball profit: 19000 - 300 - 18000 = 700; gold: -5
        assertEquals(695, totals.getProfit());
        assertEquals(302, totals.getTax());
        assertEquals(2, totals.getFlips());
    }
}

package com.osrsge.plugin.api;

import com.google.gson.Gson;
import com.google.gson.JsonObject;
import com.osrsge.plugin.model.CompletedTrade;
import com.osrsge.plugin.model.OfferOutcome;
import com.osrsge.plugin.model.TradeOffer;
import net.runelite.api.GrandExchangeOfferState;
import org.junit.Test;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertTrue;

/** Pins the JSON field names the osrsge.io backend contract depends on. */
public class PayloadContractTest
{
    private final Gson gson = new Gson();

    @Test
    public void tradeSerializesContractFields()
    {
        CompletedTrade trade = CompletedTrade.builder()
            .itemId(444)
            .itemName("Gold ore")
            .buyPrice(145)
            .sellPrice(142)
            .quantity(1)
            .profit(-5)
            .tax(2)
            .buyTimestamp(1783265377587L)
            .sellTimestamp(1783265397987L)
            .synced(false)
            .build();

        JsonObject json = gson.toJsonTree(trade).getAsJsonObject();

        assertEquals(444, json.get("itemId").getAsInt());
        assertEquals("Gold ore", json.get("itemName").getAsString());
        assertEquals(145, json.get("buyPrice").getAsInt());
        assertEquals(142, json.get("sellPrice").getAsInt());
        assertEquals(1, json.get("quantity").getAsInt());
        assertEquals(-5, json.get("profit").getAsLong());
        assertEquals(2, json.get("tax").getAsLong());
        assertEquals(1783265377587L, json.get("buyTimestamp").getAsLong());
        assertEquals(1783265397987L, json.get("sellTimestamp").getAsLong());
    }

    @Test
    public void outcomeSerializesContractFields()
    {
        OfferOutcome outcome = OfferOutcome.builder()
            .itemId(444)
            .itemName("Gold ore")
            .isBuy(true)
            .price(145)
            .totalQuantity(100)
            .quantityFilled(37)
            .placedTimestamp(1783265377587L)
            .endedTimestamp(1783265397987L)
            .cancelled(true)
            .synced(false)
            .build();

        JsonObject json = gson.toJsonTree(outcome).getAsJsonObject();

        assertEquals(444, json.get("itemId").getAsInt());
        assertEquals("Gold ore", json.get("itemName").getAsString());
        assertTrue(json.get("isBuy").getAsBoolean());
        assertEquals(145, json.get("price").getAsInt());
        assertEquals(100, json.get("totalQuantity").getAsInt());
        assertEquals(37, json.get("quantityFilled").getAsInt());
        assertEquals(1783265377587L, json.get("placedTimestamp").getAsLong());
        assertEquals(1783265397987L, json.get("endedTimestamp").getAsLong());
        assertTrue(json.get("cancelled").getAsBoolean());
    }

    @Test
    public void offerSerializesContractFields()
    {
        TradeOffer offer = TradeOffer.builder()
            .slot(2)
            .itemId(444)
            .itemName("Gold ore")
            .price(145)
            .totalQuantity(100)
            .quantityFilled(40)
            .amountSpent(5800)
            .state(GrandExchangeOfferState.BUYING)
            .isBuy(true)
            .timestamp(1783265377587L)
            .build();

        JsonObject json = gson.toJsonTree(offer).getAsJsonObject();

        assertEquals(2, json.get("slot").getAsInt());
        assertEquals(444, json.get("itemId").getAsInt());
        assertEquals("Gold ore", json.get("itemName").getAsString());
        assertEquals(145, json.get("price").getAsInt());
        assertEquals(100, json.get("totalQuantity").getAsInt());
        assertEquals(40, json.get("quantityFilled").getAsInt());
        assertEquals(5800, json.get("amountSpent").getAsLong());
        assertEquals("BUYING", json.get("state").getAsString());
        assertTrue(json.get("isBuy").getAsBoolean());
        assertEquals(1783265377587L, json.get("timestamp").getAsLong());
    }
}

