package com.osrsge.plugin.overlay;

import com.osrsge.plugin.GETrackerConfig;
import com.osrsge.plugin.GETrackerPlugin;
import com.osrsge.plugin.model.SessionStats;
import com.osrsge.plugin.model.TradeOffer;
import net.runelite.api.Client;
import net.runelite.client.ui.overlay.OverlayPanel;
import net.runelite.client.ui.overlay.OverlayPosition;
import net.runelite.client.ui.overlay.OverlayPriority;
import net.runelite.client.ui.overlay.components.LineComponent;
import net.runelite.client.ui.overlay.components.TitleComponent;

import javax.inject.Inject;
import java.awt.*;
import java.util.List;

public class GETrackerOverlay extends OverlayPanel
{
    private final Client client;
    private final GETrackerPlugin plugin;
    private final GETrackerConfig config;

    @Inject
    public GETrackerOverlay(Client client, GETrackerPlugin plugin, GETrackerConfig config)
    {
        super(plugin);
        this.client = client;
        this.plugin = plugin;
        this.config = config;
        setPosition(OverlayPosition.TOP_LEFT);
        setPriority(OverlayPriority.MED);
    }

    @Override
    public Dimension render(Graphics2D graphics)
    {
        // Widget group 465 is the Grand Exchange interface
        if (!config.showOverlay() || client.getWidget(465, 0) == null)
        {
            return null;
        }

        SessionStats stats = plugin.getSessionStats();

        panelComponent.getChildren().add(TitleComponent.builder()
            .text("GE Tracker")
            .color(new Color(0, 200, 83))
            .build());

        if (config.showSessionProfit())
        {
            long profit = stats.getTotalProfit();
            Color profitColor = profit >= 0 ? new Color(0, 200, 83) : new Color(255, 80, 80);

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Session Profit:")
                .right(formatGp(profit))
                .rightColor(profitColor)
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Flips:")
                .right(String.valueOf(stats.getTotalFlips()))
                .build());

            panelComponent.getChildren().add(LineComponent.builder()
                .left("Session:")
                .right(stats.getSessionDurationFormatted())
                .build());
        }

        if (config.showActiveFlips())
        {
            List<TradeOffer> activeOffers = plugin.getActiveOffers();
            if (!activeOffers.isEmpty())
            {
                panelComponent.getChildren().add(TitleComponent.builder()
                    .text("Active Offers (" + activeOffers.size() + ")")
                    .color(Color.YELLOW)
                    .build());

                for (TradeOffer offer : activeOffers)
                {
                    String action = offer.isBuy() ? "BUY" : "SELL";
                    String progress = offer.getQuantityFilled() + "/" + offer.getTotalQuantity();
                    Color actionColor = offer.isBuy() ? new Color(100, 180, 255) : new Color(255, 180, 100);

                    panelComponent.getChildren().add(LineComponent.builder()
                        .left(action + " " + offer.getItemName())
                        .leftColor(actionColor)
                        .right(progress)
                        .build());
                }
            }
        }

        // Sync status indicator
        String syncStatus = plugin.isSyncConnected() ? "Connected" : "Offline";
        Color syncColor = plugin.isSyncConnected() ? new Color(0, 200, 83) : Color.GRAY;
        panelComponent.getChildren().add(LineComponent.builder()
            .left("Sync:")
            .right(syncStatus)
            .rightColor(syncColor)
            .build());

        return super.render(graphics);
    }

    private String formatGp(long amount)
    {
        if (Math.abs(amount) >= 1_000_000_000)
        {
            return String.format("%.1fB gp", amount / 1_000_000_000.0);
        }
        else if (Math.abs(amount) >= 1_000_000)
        {
            return String.format("%.1fM gp", amount / 1_000_000.0);
        }
        else if (Math.abs(amount) >= 1_000)
        {
            return String.format("%.1fK gp", amount / 1_000.0);
        }
        return amount + " gp";
    }
}

package com.osrsge.plugin.model;

import lombok.Builder;
import lombok.Data;
import net.runelite.api.GrandExchangeOfferState;

@Data
@Builder
public class TradeOffer
{
    private int slot;
    private int itemId;
    private String itemName;
    private int price;
    private int totalQuantity;
    private int quantityFilled;
    private long amountSpent;
    private GrandExchangeOfferState state;
    private boolean isBuy;
    private long timestamp;
    // when the offer was first placed in the slot; survives relogs so
    // buys that fill while logged out keep their true start time
    private long placedTimestamp;

    public boolean isComplete()
    {
        return state == GrandExchangeOfferState.BOUGHT
            || state == GrandExchangeOfferState.SOLD
            || state == GrandExchangeOfferState.CANCELLED_BUY
            || state == GrandExchangeOfferState.CANCELLED_SELL;
    }

    public boolean isActive()
    {
        return state == GrandExchangeOfferState.BUYING
            || state == GrandExchangeOfferState.SELLING;
    }

    public int getAveragePrice()
    {
        if (quantityFilled == 0) return price;
        return (int) (amountSpent / quantityFilled);
    }
}

package com.osrsge.plugin.model;

import lombok.Value;

import java.util.ArrayList;
import java.util.LinkedHashMap;
import java.util.List;
import java.util.Map;

/**
 * Pure aggregation of completed trades for panel display: per-item stats
 * and overall totals, filtered by a sell-timestamp cutoff (0 = all time).
 */
public final class TradeAggregator
{
    private TradeAggregator()
    {
    }

    @Value
    public static class ItemStats
    {
        int itemId;
        String itemName;
        long totalProfit;
        long totalTax;
        int flips;
        int quantity;
        long totalBuyCost;
        long totalSellValue;
        long lastSellTimestamp;

        public long getAvgProfitEach()
        {
            return quantity == 0 ? 0 : totalProfit / quantity;
        }

        public int getAvgBuyPrice()
        {
            return quantity == 0 ? 0 : (int) (totalBuyCost / quantity);
        }

        public int getAvgSellPrice()
        {
            return quantity == 0 ? 0 : (int) (totalSellValue / quantity);
        }

        public double getRoi()
        {
            return totalBuyCost == 0 ? 0 : ((double) totalProfit / totalBuyCost) * 100;
        }
    }

    @Value
    public static class Totals
    {
        long profit;
        long tax;
        int flips;
    }

    public static List<ItemStats> aggregate(List<CompletedTrade> trades, long cutoffTimestamp)
    {
        Map<Integer, Builder> byItem = new LinkedHashMap<>();
        for (CompletedTrade t : trades)
        {
            if (t.getSellTimestamp() < cutoffTimestamp)
            {
                continue;
            }
            Builder b = byItem.computeIfAbsent(t.getItemId(), k -> new Builder(t.getItemId(), t.getItemName()));
            b.profit += t.getProfit();
            b.tax += t.getTax();
            b.flips++;
            b.quantity += t.getQuantity();
            b.buyCost += (long) t.getBuyPrice() * t.getQuantity();
            b.sellValue += (long) t.getSellPrice() * t.getQuantity();
            b.lastSell = Math.max(b.lastSell, t.getSellTimestamp());
        }

        List<ItemStats> out = new ArrayList<>();
        for (Builder b : byItem.values())
        {
            out.add(new ItemStats(b.itemId, b.itemName, b.profit, b.tax, b.flips,
                b.quantity, b.buyCost, b.sellValue, b.lastSell));
        }
        out.sort((a, c) -> Long.compare(c.getLastSellTimestamp(), a.getLastSellTimestamp()));
        return out;
    }

    public static Totals totals(List<CompletedTrade> trades, long cutoffTimestamp)
    {
        long profit = 0;
        long tax = 0;
        int flips = 0;
        for (CompletedTrade t : trades)
        {
            if (t.getSellTimestamp() < cutoffTimestamp)
            {
                continue;
            }
            profit += t.getProfit();
            tax += t.getTax();
            flips++;
        }
        return new Totals(profit, tax, flips);
    }

    private static class Builder
    {
        final int itemId;
        final String itemName;
        long profit;
        long tax;
        int flips;
        int quantity;
        long buyCost;
        long sellValue;
        long lastSell;

        Builder(int itemId, String itemName)
        {
            this.itemId = itemId;
            this.itemName = itemName;
        }
    }
}

package com.osrsge.plugin.model;

import lombok.Data;

import java.time.Instant;

@Data
public class SessionStats
{
    private final Instant sessionStart = Instant.now();
    private long totalProfit = 0;
    private long totalTax = 0;
    private int totalFlips = 0;
    private int totalBuys = 0;
    private int totalSells = 0;

    public void recordFlip(CompletedTrade trade)
    {
        totalProfit += trade.getProfit();
        totalTax += trade.getTax();
        totalFlips++;
    }

    public void recordBuy()
    {
        totalBuys++;
    }

    public void recordSell()
    {
        totalSells++;
    }

    public long getSessionDurationSeconds()
    {
        return Instant.now().getEpochSecond() - sessionStart.getEpochSecond();
    }

    public String getSessionDurationFormatted()
    {
        long seconds = getSessionDurationSeconds();
        long hours = seconds / 3600;
        long minutes = (seconds % 3600) / 60;
        long secs = seconds % 60;
        return String.format("%02d:%02d:%02d", hours, minutes, secs);
    }

}

package com.osrsge.plugin.model;

import java.util.Set;

/**
 * Grand Exchange sell tax: 2% per item rounded down, capped at 5m gp
 * per item. Items under 50 gp and exempt items pay nothing.
 */
public final class GeTax
{
    public static final int OLD_SCHOOL_BOND = 13190;
    public static final long TAX_CAP_PER_ITEM = 5_000_000L;

    // Bond + low-level skilling tools are tax-exempt
    private static final Set<Integer> EXEMPT_ITEMS = Set.of(
        OLD_SCHOOL_BOND,
        1755,  // Chisel
        5325,  // Gardening trowel
        1785,  // Glassblowing pipe
        2347,  // Hammer
        1733,  // Needle
        233,   // Pestle and mortar
        5341,  // Rake
        8794,  // Saw
        5329,  // Secateurs
        5343,  // Seed dibber
        1735,  // Shears
        952,   // Spade
        5331   // Watering can (0)
    );

    private GeTax()
    {
    }

    /** Tax in gp charged on ONE item sold at pricePerItem. */
    public static long taxFor(int itemId, long pricePerItem)
    {
        if (EXEMPT_ITEMS.contains(itemId))
        {
            return 0;
        }
        return Math.min(pricePerItem / 50, TAX_CAP_PER_ITEM);
    }
}

package com.osrsge.plugin.model;

import lombok.AllArgsConstructor;
import lombok.Data;
import lombok.NoArgsConstructor;

/** One completed buy sitting in the FIFO ledger, partially or fully unmatched. */
@Data
@NoArgsConstructor
@AllArgsConstructor
public class BuyEntry
{
    private int itemId;
    private int remaining;
    private int price;      // average gp paid per item
    private long timestamp;
}

package com.osrsge.plugin.model;

import lombok.Builder;
import lombok.Data;

/**
 * Terminal result of one GE offer, recorded whether or not it filled.
 * Feeds fill-rate statistics: which items buy/sell fully, partially,
 * or not at all.
 */
@Data
@Builder
public class OfferOutcome
{
    private int itemId;
    private String itemName;
    private boolean isBuy;
    private int price;             // offered price per item
    private int totalQuantity;     // requested
    private int quantityFilled;    // actually traded (0 = never filled)
    private long placedTimestamp;  // when the offer was placed
    private long endedTimestamp;   // when it completed or was cancelled
    private boolean cancelled;     // true = player cancelled before full fill
    private boolean synced;
}

package com.osrsge.plugin.model;

import java.util.ArrayDeque;
import java.util.ArrayList;
import java.util.Deque;
import java.util.HashMap;
import java.util.List;
import java.util.Map;

/**
 * FIFO buy ledger per item. Sells consume the oldest buys first;
 * each sell produces one CompletedTrade with exact cost math and GE tax.
 */
public class FlipTracker
{
    private final Map<Integer, Deque<BuyEntry>> buyLedger = new HashMap<>();

    public void recordBuy(int itemId, int quantity, int avgPrice, long timestamp)
    {
        if (quantity <= 0)
        {
            return;
        }
        buyLedger.computeIfAbsent(itemId, k -> new ArrayDeque<>())
            .addLast(new BuyEntry(itemId, quantity, avgPrice, timestamp));
    }

    /**
     * Match a completed sell against the ledger. Returns null when no
     * buys exist for the item (nothing to flip against).
     */
    public CompletedTrade matchSell(int itemId, String itemName, int quantity, int sellAvgPrice, long timestamp)
    {
        Deque<BuyEntry> buys = buyLedger.get(itemId);
        if (buys == null || buys.isEmpty() || quantity <= 0)
        {
            return null;
        }

        int matched = 0;
        long totalBuyCost = 0;
        long firstBuyTimestamp = buys.peekFirst().getTimestamp();

        while (matched < quantity && !buys.isEmpty())
        {
            BuyEntry oldest = buys.peekFirst();
            int take = Math.min(oldest.getRemaining(), quantity - matched);
            matched += take;
            totalBuyCost += (long) take * oldest.getPrice();
            oldest.setRemaining(oldest.getRemaining() - take);
            if (oldest.getRemaining() == 0)
            {
                buys.pollFirst();
            }
        }

        long taxPerItem = GeTax.taxFor(itemId, sellAvgPrice);
        long totalTax = taxPerItem * matched;
        long profit = (long) sellAvgPrice * matched - totalTax - totalBuyCost;

        return CompletedTrade.builder()
            .itemId(itemId)
            .itemName(itemName)
            .buyPrice((int) (totalBuyCost / matched))
            .sellPrice(sellAvgPrice)
            .quantity(matched)
            .tax(totalTax)
            .profit(profit)
            .buyTimestamp(firstBuyTimestamp)
            .sellTimestamp(timestamp)
            .synced(false)
            .build();
    }

    public int unmatchedQuantity(int itemId)
    {
        Deque<BuyEntry> buys = buyLedger.get(itemId);
        if (buys == null)
        {
            return 0;
        }
        return buys.stream().mapToInt(BuyEntry::getRemaining).sum();
    }

    /** Flat copy of all ledger entries, oldest first per item, for persistence. */
    public List<BuyEntry> snapshot()
    {
        List<BuyEntry> out = new ArrayList<>();
        buyLedger.values().forEach(out::addAll);
        return out;
    }

    public void restore(List<BuyEntry> entries)
    {
        buyLedger.clear();
        if (entries == null)
        {
            return;
        }
        for (BuyEntry e : entries)
        {
            if (e.getRemaining() > 0)
            {
                buyLedger.computeIfAbsent(e.getItemId(), k -> new ArrayDeque<>()).addLast(e);
            }
        }
    }

    public void clear()
    {
        buyLedger.clear();
    }
}

package com.osrsge.plugin.model;

import lombok.Builder;
import lombok.Data;

@Data
@Builder
public class CompletedTrade
{
    private int itemId;
    private String itemName;
    private int buyPrice;
    private int sellPrice;
    private int quantity;
    private long profit;
    private long tax;
    private long buyTimestamp;
    private long sellTimestamp;
    private boolean synced;

    public int getMargin()
    {
        return sellPrice - buyPrice;
    }

    public double getRoi()
    {
        if (buyPrice == 0) return 0;
        return ((double) getMargin() / buyPrice) * 100;
    }
}

package com.osrsge.plugin.model;

import java.util.HashMap;
import java.util.Map;
import net.runelite.api.GrandExchangeOfferState;

/**
 * Drops repeated GrandExchangeOfferChanged events. The GE fires the same
 * terminal state more than once (seen live: double CANCELLED_SELL) and
 * replays last-known state on login.
 */
public class OfferEventDeduper
{
    private final Map<Integer, String> lastSeen = new HashMap<>();

    public boolean isDuplicate(int slot, GrandExchangeOfferState state, int quantityFilled, long spent)
    {
        String key = key(state, quantityFilled, spent);
        return key.equals(lastSeen.put(slot, key));
    }

    /** Prime a slot with persisted state so login replays are dropped. */
    public void seed(int slot, GrandExchangeOfferState state, int quantityFilled, long spent)
    {
        lastSeen.put(slot, key(state, quantityFilled, spent));
    }

    public void clearSlot(int slot)
    {
        lastSeen.remove(slot);
    }

    public void clear()
    {
        lastSeen.clear();
    }

    private static String key(GrandExchangeOfferState state, int quantityFilled, long spent)
    {
        return state + ":" + quantityFilled + ":" + spent;
    }
}

package com.osrsge.plugin.ui;

import com.osrsge.plugin.GETrackerPlugin;
import com.osrsge.plugin.model.CompletedTrade;
import com.osrsge.plugin.model.SessionStats;
import com.osrsge.plugin.model.TradeAggregator;
