import net.runelite.client.ui.PluginPanel;
import net.runelite.client.util.AsyncBufferedImage;
import net.runelite.client.util.LinkBrowser;

import javax.swing.*;
import javax.swing.border.EmptyBorder;
import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import java.util.ArrayList;
import java.util.List;

public class GETrackerPanel extends PluginPanel
{
    private static final Color GREEN = new Color(0, 200, 83);
    private static final Color RED = new Color(255, 80, 80);
    private static final Color ORANGE = new Color(255, 180, 100);
    private static final Color BLUE = new Color(100, 180, 255);
    private static final Color ROW_BG = new Color(40, 40, 40);
    private static final Color ROW_HOVER_BG = new Color(50, 50, 50);

    private enum Range
    {
        SESSION("Session", -1),
        HOUR_1("Past Hour", 3_600_000L),
        HOUR_4("Past 4 Hours", 4 * 3_600_000L),
        HOUR_12("Past 12 Hours", 12 * 3_600_000L),
        DAY_1("Past Day", 24 * 3_600_000L),
        WEEK_1("Past Week", 7 * 24 * 3_600_000L),
        MONTH_1("Past Month", 30L * 24 * 3_600_000L),
        ALL("All", 0);

        final String label;
        final long windowMillis; // -1 = session start, 0 = everything

        Range(String label, long windowMillis)
        {
            this.label = label;
            this.windowMillis = windowMillis;
        }

        @Override
        public String toString()
        {
            return label;
        }
    }

    private final GETrackerPlugin plugin;

    private final JLabel profitLabel = new JLabel("0 gp");
    private final JLabel flipsLabel = new JLabel("0");
    private final JLabel taxLabel = new JLabel("0 gp");
    private final JLabel sessionTimeLabel = new JLabel("00:00:00");
    private final JLabel syncStatusLabel = new JLabel("Offline");

    private final JComboBox<Range> rangeCombo = new JComboBox<>(Range.values());

    private final JPanel activeOffersPanel = new JPanel();
    private final JPanel itemsPanel = new JPanel();

    private List<CompletedTrade> latestTrades = new ArrayList<>();

    public GETrackerPanel(GETrackerPlugin plugin)
    {
        super(false);
        this.plugin = plugin;

        setLayout(new BorderLayout());
        setBackground(ColorScheme.DARK_GRAY_COLOR);

        add(buildMainPanel(), BorderLayout.NORTH);
    }

    private JPanel buildMainPanel()
    {
        JPanel container = new JPanel();
        container.setLayout(new BoxLayout(container, BoxLayout.Y_AXIS));
        container.setBackground(ColorScheme.DARK_GRAY_COLOR);

        container.add(buildHeaderPanel());
        container.add(Box.createVerticalStrut(8));
        container.add(buildRangePanel());
        container.add(Box.createVerticalStrut(8));
        container.add(buildStatsPanel());
        container.add(Box.createVerticalStrut(8));
        container.add(buildActiveOffersSection());
        container.add(Box.createVerticalStrut(8));
        container.add(buildItemsSection());
        container.add(Box.createVerticalStrut(8));
        container.add(buildActionsPanel());

        return container;
    }

    private JPanel buildHeaderPanel()
    {
        JPanel header = new JPanel(new BorderLayout());
        header.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        header.setBorder(new EmptyBorder(10, 10, 10, 10));

        JLabel title = new JLabel("OSRS GE Tracker");
        title.setFont(FontManager.getRunescapeBoldFont());
        title.setForeground(GREEN);
        header.add(title, BorderLayout.WEST);

        syncStatusLabel.setFont(FontManager.getRunescapeSmallFont());
        syncStatusLabel.setForeground(Color.GRAY);
        header.add(syncStatusLabel, BorderLayout.EAST);

        return header;
    }

    private JPanel buildRangePanel()
    {
        JPanel rangePanel = new JPanel(new BorderLayout());
        rangePanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        rangePanel.setBorder(new EmptyBorder(6, 10, 6, 10));

        rangeCombo.setFont(FontManager.getRunescapeSmallFont());
        rangeCombo.setFocusable(false);
        rangeCombo.addActionListener(e -> render());
        rangePanel.add(rangeCombo, BorderLayout.CENTER);

        return rangePanel;
    }

    private JPanel buildStatsPanel()
    {
        JPanel stats = new JPanel(new GridLayout(4, 2, 5, 5));
        stats.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        stats.setBorder(new EmptyBorder(10, 10, 10, 10));

        stats.add(createLabel("Profit:", Color.WHITE));
        profitLabel.setForeground(GREEN);
        profitLabel.setHorizontalAlignment(SwingConstants.RIGHT);
        stats.add(profitLabel);

        stats.add(createLabel("Flips:", Color.WHITE));
        flipsLabel.setForeground(Color.WHITE);
        flipsLabel.setHorizontalAlignment(SwingConstants.RIGHT);
        stats.add(flipsLabel);

        stats.add(createLabel("Tax Paid:", Color.WHITE));
        taxLabel.setForeground(ORANGE);
        taxLabel.setHorizontalAlignment(SwingConstants.RIGHT);
        stats.add(taxLabel);

        stats.add(createLabel("Session:", Color.WHITE));
        sessionTimeLabel.setForeground(Color.WHITE);
        sessionTimeLabel.setHorizontalAlignment(SwingConstants.RIGHT);
        stats.add(sessionTimeLabel);

        return stats;
    }

    private JPanel buildActiveOffersSection()
    {
        JPanel section = new JPanel(new BorderLayout());
        section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        section.setBorder(new EmptyBorder(5, 10, 5, 10));

        JLabel sectionTitle = new JLabel("Active Offers");
        sectionTitle.setForeground(Color.YELLOW);
        sectionTitle.setFont(FontManager.getRunescapeSmallFont());
        section.add(sectionTitle, BorderLayout.NORTH);

        activeOffersPanel.setLayout(new BoxLayout(activeOffersPanel, BoxLayout.Y_AXIS));
        activeOffersPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        section.add(activeOffersPanel, BorderLayout.CENTER);

        return section;
    }

    private JPanel buildItemsSection()
    {
        JPanel section = new JPanel(new BorderLayout());
        section.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        section.setBorder(new EmptyBorder(5, 10, 5, 10));

        JLabel sectionTitle = new JLabel("Items");
        sectionTitle.setForeground(BLUE);
        sectionTitle.setFont(FontManager.getRunescapeSmallFont());
        section.add(sectionTitle, BorderLayout.NORTH);

        itemsPanel.setLayout(new BoxLayout(itemsPanel, BoxLayout.Y_AXIS));
        itemsPanel.setBackground(ColorScheme.DARKER_GRAY_COLOR);

        JScrollPane scrollPane = new JScrollPane(itemsPanel);
        scrollPane.setPreferredSize(new Dimension(0, 260));
        scrollPane.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        scrollPane.setBorder(null);
        section.add(scrollPane, BorderLayout.CENTER);

        return section;
    }

    private JPanel buildActionsPanel()
    {
        JPanel actions = new JPanel(new GridLayout(2, 1, 5, 5));
        actions.setBackground(ColorScheme.DARK_GRAY_COLOR);
        actions.setBorder(new EmptyBorder(5, 10, 10, 10));

        JButton openWebButton = new JButton("Open Dashboard");
        openWebButton.setFocusPainted(false);
        openWebButton.addActionListener(e -> LinkBrowser.browse("https://osrsge.io/"));
        actions.add(openWebButton);

        JButton resetButton = new JButton("Reset Session");
        resetButton.setFocusPainted(false);
        resetButton.addActionListener(e -> {
            plugin.resetSession();
            render();
        });
        actions.add(resetButton);

        return actions;
    }

    // --- update entry points (called from plugin) ---

    public void updateStats()
    {
        SwingUtilities.invokeLater(this::render);
    }

    public void updateActiveOffers(List<TradeOffer> offers)
    {
        SwingUtilities.invokeLater(() -> {
            activeOffersPanel.removeAll();

            if (offers.isEmpty())
            {
                JLabel empty = new JLabel("No active offers");
                empty.setForeground(Color.GRAY);
                empty.setFont(FontManager.getRunescapeSmallFont());
                activeOffersPanel.add(empty);
            }
            else
            {
                for (TradeOffer offer : offers)
                {
                    activeOffersPanel.add(createOfferRow(offer));
                }
            }

            activeOffersPanel.revalidate();
            activeOffersPanel.repaint();
        });
    }

    public void updateTradeHistory(List<CompletedTrade> trades)
    {
        SwingUtilities.invokeLater(() -> {
            latestTrades = new ArrayList<>(trades);
            render();
        });
    }

    // --- rendering ---

    private long cutoff()
    {
        Range range = (Range) rangeCombo.getSelectedItem();
        if (range == null || range == Range.ALL)
        {
            return 0;
        }
        if (range == Range.SESSION)
        {
            return plugin.getSessionStats().getSessionStart().toEpochMilli();
        }
        return System.currentTimeMillis() - range.windowMillis;
    }

    private void render()
    {
        SessionStats session = plugin.getSessionStats();
        Range range = (Range) rangeCombo.getSelectedItem();
        long cutoff = cutoff();

        TradeAggregator.Totals totals = TradeAggregator.totals(latestTrades, cutoff);
        Color profitColor = totals.getProfit() >= 0 ? GREEN : RED;

        profitLabel.setText(formatGp(totals.getProfit()));
        profitLabel.setForeground(profitColor);

        flipsLabel.setText(String.valueOf(totals.getFlips()));
        taxLabel.setText(formatGp(totals.getTax()));
        sessionTimeLabel.setText(session.getSessionDurationFormatted());

        boolean connected = plugin.isSyncConnected();
        syncStatusLabel.setText(connected ? "Synced" : "Offline");
        syncStatusLabel.setForeground(connected ? GREEN : Color.GRAY);

        renderItems(cutoff);
    }

    private void renderItems(long cutoff)
    {
        itemsPanel.removeAll();

        List<TradeAggregator.ItemStats> items = TradeAggregator.aggregate(latestTrades, cutoff);
        if (items.isEmpty())
        {
            JLabel empty = new JLabel("No completed trades yet");
            empty.setForeground(Color.GRAY);
            empty.setFont(FontManager.getRunescapeSmallFont());
            itemsPanel.add(empty);
        }
        else
        {
            int shown = 0;
            for (TradeAggregator.ItemStats item : items)
            {
                if (shown++ >= 25)
                {
                    break;
                }
                itemsPanel.add(new ItemRow(item));
                itemsPanel.add(Box.createVerticalStrut(2));
            }
        }

        itemsPanel.revalidate();
        itemsPanel.repaint();
    }

    /** Expandable per-item row: header line + click-to-toggle details. */
    private class ItemRow extends JPanel
    {
        private final JPanel details;
        private final JLabel arrow;

        ItemRow(TradeAggregator.ItemStats item)
        {
            setLayout(new BorderLayout());
            setBackground(ROW_BG);

            JPanel headerRow = new JPanel(new BorderLayout());
            headerRow.setBackground(ROW_BG);
            headerRow.setBorder(new EmptyBorder(5, 6, 5, 6));

            arrow = new JLabel("▶");
            arrow.setForeground(Color.GRAY);
            // default Swing font: the RuneScape font lacks the triangle glyphs
            arrow.setFont(arrow.getFont().deriveFont(9f));
            arrow.setBorder(new EmptyBorder(0, 0, 0, 6));

            JLabel icon = new JLabel();
            icon.setBorder(new EmptyBorder(0, 0, 0, 6));
            AsyncBufferedImage itemImage = plugin.getItemManager()
                .getImage(item.getItemId(), item.getQuantity(), item.getQuantity() > 1);
            itemImage.addTo(icon);

            JLabel name = new JLabel(item.getItemName());
            name.setForeground(Color.WHITE);
            name.setFont(FontManager.getRunescapeSmallFont());

            JPanel left = new JPanel(new BorderLayout());
            left.setOpaque(false);
            left.add(arrow, BorderLayout.WEST);
            left.add(icon, BorderLayout.CENTER);
            left.add(name, BorderLayout.EAST);
            headerRow.add(left, BorderLayout.WEST);

            Color profitColor = item.getTotalProfit() >= 0 ? GREEN : RED;
            String sign = item.getTotalProfit() >= 0 ? "+" : "";
            JLabel profit = new JLabel(sign + formatGp(item.getTotalProfit()));
            profit.setForeground(profitColor);
            profit.setFont(FontManager.getRunescapeSmallFont());
            headerRow.add(profit, BorderLayout.EAST);

            details = buildDetails(item);
            details.setVisible(false);

            add(headerRow, BorderLayout.NORTH);
            add(details, BorderLayout.CENTER);

            MouseAdapter toggle = new MouseAdapter()
            {
                @Override
                public void mouseClicked(MouseEvent e)
                {
                    boolean open = !details.isVisible();
                    details.setVisible(open);
                    arrow.setText(open ? "▼" : "▶");
                    itemsPanel.revalidate();
                }

                @Override
                public void mouseEntered(MouseEvent e)
                {
                    headerRow.setBackground(ROW_HOVER_BG);
                }

                @Override
                public void mouseExited(MouseEvent e)
                {
                    headerRow.setBackground(ROW_BG);
                }
            };
            headerRow.addMouseListener(toggle);
            headerRow.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));

            setMaximumSize(new Dimension(Integer.MAX_VALUE, getPreferredSize().height + 400));
        }

        private JPanel buildDetails(TradeAggregator.ItemStats item)
        {
            JPanel grid = new JPanel(new GridLayout(7, 2, 4, 3));
            grid.setBackground(ROW_BG);
            grid.setBorder(new EmptyBorder(2, 18, 6, 6));

            Color profitColor = item.getTotalProfit() >= 0 ? GREEN : RED;

            addDetail(grid, "Total Profit:", formatGp(item.getTotalProfit()), profitColor);
            addDetail(grid, "Avg Profit ea:", formatGp(item.getAvgProfitEach()) + "/ea", profitColor);
            addDetail(grid, "Avg ROI:", String.format("%.2f%%", item.getRoi()), profitColor);
            addDetail(grid, "Flips:", String.valueOf(item.getFlips()), Color.WHITE);
            addDetail(grid, "Avg Buy Price:", formatGp(item.getAvgBuyPrice()), Color.WHITE);
            addDetail(grid, "Avg Sell Price:", formatGp(item.getAvgSellPrice()), Color.WHITE);
            addDetail(grid, "Tax Paid:", formatGp(item.getTotalTax()), ORANGE);

            return grid;
        }

        private void addDetail(JPanel grid, String key, String value, Color valueColor)
        {
            JLabel k = new JLabel(key);
            k.setForeground(Color.LIGHT_GRAY);
            k.setFont(FontManager.getRunescapeSmallFont());
            grid.add(k);

            JLabel v = new JLabel(value);
            v.setForeground(valueColor);
            v.setFont(FontManager.getRunescapeSmallFont());
            v.setHorizontalAlignment(SwingConstants.RIGHT);
            grid.add(v);
        }
    }

    private JPanel createOfferRow(TradeOffer offer)
    {
        JPanel row = new JPanel(new BorderLayout());
        row.setBackground(ColorScheme.DARKER_GRAY_COLOR);
        row.setBorder(new EmptyBorder(3, 0, 3, 0));

        String action = offer.isBuy() ? "BUY" : "SELL";
        Color actionColor = offer.isBuy() ? BLUE : ORANGE;

        JLabel iconLabel = new JLabel();
        iconLabel.setBorder(new EmptyBorder(0, 0, 0, 6));
        AsyncBufferedImage itemImage = plugin.getItemManager()
            .getImage(offer.getItemId(), offer.getTotalQuantity(), offer.getTotalQuantity() > 1);
        itemImage.addTo(iconLabel);

        JLabel nameLabel = new JLabel(action + " " + offer.getItemName());
        nameLabel.setForeground(actionColor);
        nameLabel.setFont(FontManager.getRunescapeSmallFont());

        JPanel left = new JPanel(new BorderLayout());
        left.setOpaque(false);
        left.add(iconLabel, BorderLayout.WEST);
        left.add(nameLabel, BorderLayout.CENTER);
        row.add(left, BorderLayout.WEST);

        String progress = offer.getQuantityFilled() + "/" + offer.getTotalQuantity();
        JLabel progressLabel = new JLabel(progress + " @ " + formatGp(offer.getPrice()));
        progressLabel.setForeground(Color.LIGHT_GRAY);
        progressLabel.setFont(FontManager.getRunescapeSmallFont());
        row.add(progressLabel, BorderLayout.EAST);

        return row;
    }

    private JLabel createLabel(String text, Color color)
    {
        JLabel label = new JLabel(text);
        label.setForeground(color);
        return label;
    }

    private String formatGp(long amount)
    {
        if (Math.abs(amount) >= 1_000_000_000)
        {
            return String.format("%.1fB", amount / 1_000_000_000.0);
        }
        else if (Math.abs(amount) >= 1_000_000)
        {
            return String.format("%.1fM", amount / 1_000_000.0);
        }
        else if (Math.abs(amount) >= 1_000)
        {
            return String.format("%.1fK", amount / 1_000.0);
        }
        return amount + " gp";
    }
}

package com.osrsge.plugin.db;

import com.google.gson.Gson;
import com.google.gson.reflect.TypeToken;
import com.osrsge.plugin.model.BuyEntry;
import com.osrsge.plugin.model.CompletedTrade;
import com.osrsge.plugin.model.OfferOutcome;
import com.osrsge.plugin.model.TradeOffer;
import lombok.extern.slf4j.Slf4j;

import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.lang.reflect.Type;
import java.util.ArrayList;
import java.util.List;

import static net.runelite.client.RuneLite.RUNELITE_DIR;

@Slf4j
public class TradeStorage
{
    private static final File PLUGIN_DIR = new File(RUNELITE_DIR, "osrsge-tracker");
    private final Gson gson;

    public TradeStorage(Gson gson)
    {
        this.gson = gson;
        PLUGIN_DIR.mkdirs();
    }

    private File getTradesFile(String playerName)
    {
        return new File(PLUGIN_DIR, playerName.toLowerCase().replace(" ", "_") + "_trades.json");
    }

    private File getOffersFile(String playerName)
    {
        return new File(PLUGIN_DIR, playerName.toLowerCase().replace(" ", "_") + "_offers.json");
    }

    private File getLedgerFile(String playerName)
    {
        return new File(PLUGIN_DIR, playerName.toLowerCase().replace(" ", "_") + "_ledger.json");
    }

    private File getOutcomesFile(String playerName)
    {
        return new File(PLUGIN_DIR, playerName.toLowerCase().replace(" ", "_") + "_outcomes.json");
    }

    public List<OfferOutcome> loadOutcomes(String playerName)
    {
        File file = getOutcomesFile(playerName);
        if (!file.exists()) return new ArrayList<>();

        try (FileReader reader = new FileReader(file))
        {
            Type type = new TypeToken<List<OfferOutcome>>(){}.getType();
            List<OfferOutcome> outcomes = gson.fromJson(reader, type);
            return outcomes != null ? outcomes : new ArrayList<>();
        }
        catch (IOException e)
        {
            log.error("Failed to load outcomes for {}", playerName, e);
            return new ArrayList<>();
        }
    }

    public void saveOutcomes(String playerName, List<OfferOutcome> outcomes)
    {
        File file = getOutcomesFile(playerName);
        try (FileWriter writer = new FileWriter(file))
        {
            gson.toJson(outcomes, writer);
        }
        catch (IOException e)
        {
            log.error("Failed to save outcomes for {}", playerName, e);
        }
    }

    public List<BuyEntry> loadLedger(String playerName)
    {
        File file = getLedgerFile(playerName);
        if (!file.exists()) return new ArrayList<>();

        try (FileReader reader = new FileReader(file))
        {
            Type type = new TypeToken<List<BuyEntry>>(){}.getType();
            List<BuyEntry> entries = gson.fromJson(reader, type);
            return entries != null ? entries : new ArrayList<>();
        }
        catch (IOException e)
        {
            log.error("Failed to load ledger for {}", playerName, e);
            return new ArrayList<>();
        }
    }

    public void saveLedger(String playerName, List<BuyEntry> entries)
    {
        File file = getLedgerFile(playerName);
        try (FileWriter writer = new FileWriter(file))
        {
            gson.toJson(entries, writer);
        }
        catch (IOException e)
        {
            log.error("Failed to save ledger for {}", playerName, e);
        }
    }

    public List<CompletedTrade> loadTrades(String playerName)
    {
        File file = getTradesFile(playerName);
        if (!file.exists()) return new ArrayList<>();

        try (FileReader reader = new FileReader(file))
        {
            Type type = new TypeToken<List<CompletedTrade>>(){}.getType();
            List<CompletedTrade> trades = gson.fromJson(reader, type);
            return trades != null ? trades : new ArrayList<>();
        }
        catch (IOException e)
        {
            log.error("Failed to load trades for {}", playerName, e);
            return new ArrayList<>();
        }
    }

    public void saveTrades(String playerName, List<CompletedTrade> trades)
    {
        File file = getTradesFile(playerName);
        try (FileWriter writer = new FileWriter(file))
        {
            gson.toJson(trades, writer);
        }
        catch (IOException e)
        {
            log.error("Failed to save trades for {}", playerName, e);
        }
    }

    public List<TradeOffer> loadOffers(String playerName)
    {
        File file = getOffersFile(playerName);
        if (!file.exists()) return new ArrayList<>();

        try (FileReader reader = new FileReader(file))
        {
            Type type = new TypeToken<List<TradeOffer>>(){}.getType();
            List<TradeOffer> offers = gson.fromJson(reader, type);
            return offers != null ? offers : new ArrayList<>();
        }
        catch (IOException e)
        {
            log.error("Failed to load offers for {}", playerName, e);
            return new ArrayList<>();
        }
    }

    public void saveOffers(String playerName, List<TradeOffer> offers)
    {
        File file = getOffersFile(playerName);
        try (FileWriter writer = new FileWriter(file))
        {
            gson.toJson(offers, writer);
        }
        catch (IOException e)
        {
            log.error("Failed to save offers for {}", playerName, e);
        }
    }

}

package com.osrsge.plugin;

import com.google.gson.Gson;
import com.google.inject.Provides;
import com.osrsge.plugin.api.OsrsGeApiClient;
import com.osrsge.plugin.db.TradeStorage;
import com.osrsge.plugin.model.*;
import com.osrsge.plugin.overlay.GETrackerOverlay;
import com.osrsge.plugin.ui.GETrackerPanel;
import lombok.Getter;
import lombok.extern.slf4j.Slf4j;
import net.runelite.api.*;
import net.runelite.api.events.GameStateChanged;
import net.runelite.api.events.GrandExchangeOfferChanged;
import net.runelite.client.callback.ClientThread;
import net.runelite.client.config.ConfigManager;
import net.runelite.client.eventbus.Subscribe;
import net.runelite.client.events.ConfigChanged;
import net.runelite.client.game.ItemManager;
import net.runelite.client.plugins.Plugin;
import net.runelite.client.plugins.PluginDescriptor;
import net.runelite.client.ui.ClientToolbar;
import net.runelite.client.ui.NavigationButton;
import net.runelite.client.ui.overlay.OverlayManager;
import net.runelite.client.util.ImageUtil;
import okhttp3.OkHttpClient;

import javax.inject.Inject;
import javax.swing.*;
import java.awt.image.BufferedImage;
import java.util.*;
import java.util.concurrent.*;
import java.util.stream.Collectors;

@Slf4j
@PluginDescriptor(
    name = "OSRS GE Tracker",
    description = "Tracks Grand Exchange activity and syncs with osrsge.io",
    tags = {"grand exchange", "ge", "flipping", "trading", "profit"}
)
public class GETrackerPlugin extends Plugin
{
    @Inject
    private Client client;

    @Inject
    private ClientThread clientThread;

    @Inject
    private GETrackerConfig config;

    @Getter
    @Inject
    private ItemManager itemManager;

    @Inject
    private OverlayManager overlayManager;

    @Inject
    private ClientToolbar clientToolbar;

    @Inject
    private OkHttpClient okHttpClient;

    @Inject
    private Gson gson;

    private GETrackerOverlay overlay;
    private GETrackerPanel panel;
    private NavigationButton navButton;
    private OsrsGeApiClient apiClient;
    private TradeStorage tradeStorage;

    @Getter
    private SessionStats sessionStats = new SessionStats();

    private FlipTracker flipTracker = new FlipTracker();

    private final OfferEventDeduper deduper = new OfferEventDeduper();

    // slot -> last known offer state
    private final Map<Integer, TradeOffer> slotOffers = new ConcurrentHashMap<>();

    // All completed trades for this player
    @Getter
    private List<CompletedTrade> allTrades = new ArrayList<>();

    // Terminal result of every offer, filled or not (fill-rate data)
    private List<OfferOutcome> allOutcomes = new ArrayList<>();

    private ScheduledExecutorService syncExecutor;
    private ScheduledFuture<?> syncTask;

    @Getter
    private boolean syncConnected = false;

    private String playerName;
    private boolean loggedIn = false;

    // Queue for events received before login completes
    private final List<GrandExchangeOfferChanged> pendingEvents = new ArrayList<>();

    @Provides
    GETrackerConfig provideConfig(ConfigManager configManager)
    {
        return configManager.getConfig(GETrackerConfig.class);
    }

    @Override
    protected void startUp()
    {
        apiClient = new OsrsGeApiClient(okHttpClient, gson);
        apiClient.setBaseUrl(config.syncBaseUrl());
        apiClient.setApiKey(config.apiKey());
        tradeStorage = new TradeStorage(gson);

        overlay = new GETrackerOverlay(client, this, config);
        overlayManager.add(overlay);

        panel = new GETrackerPanel(this);
        final BufferedImage icon = ImageUtil.loadImageResource(getClass(), "/ge_icon.png");
        navButton = NavigationButton.builder()
            .tooltip("GE Tracker")
            .icon(icon != null ? icon : new BufferedImage(16, 16, BufferedImage.TYPE_INT_ARGB))
            .priority(5)
            .panel(panel)
            .build();
        clientToolbar.addNavigation(navButton);

        syncExecutor = Executors.newSingleThreadScheduledExecutor();
        startSyncTask();

        // Installed or enabled mid-session: no LOGGED_IN event will arrive,
        // so initialize now and read the current GE slots directly
        if (client.getGameState() == GameState.LOGGED_IN)
        {
            initPlayerSession(true);
        }

        log.info("OSRS GE Tracker started");
    }

    /**
     * Bind to the logged-in character: load its saved data, drain queued
     * offer events, and sync immediately. The player object appears some
     * frames after LOGGED_IN, so this retries each frame until it exists.
     *
     * @param readCurrentOffers true when starting mid-session, where the
     *                          client will not replay the GE slot events
     */
    private void initPlayerSession(boolean readCurrentOffers)
    {
        clientThread.invokeLater(() -> {
            Player localPlayer = client.getLocalPlayer();
            if (localPlayer == null || localPlayer.getName() == null)
            {
                return false;
            }
            playerName = localPlayer.getName();
            loggedIn = true;

            apiClient.setPlayerName(playerName);
            apiClient.setApiKey(config.apiKey());
            apiClient.setBaseUrl(config.syncBaseUrl());

            // Load saved data
            allTrades = tradeStorage.loadTrades(playerName);
            allOutcomes = tradeStorage.loadOutcomes(playerName);
            flipTracker.restore(tradeStorage.loadLedger(playerName));
            for (TradeOffer saved : tradeStorage.loadOffers(playerName))
            {
                deduper.seed(saved.getSlot(), saved.getState(),
                    saved.getQuantityFilled(), saved.getAmountSpent());
                // restore slot state so placement timestamps survive relogs
                slotOffers.put(saved.getSlot(), saved);
            }

            // Process any pending events
            for (GrandExchangeOfferChanged pending : pendingEvents)
            {
                processOfferEvent(pending);
            }
            pendingEvents.clear();

            if (readCurrentOffers)
            {
                // same path as the login replay; the seeded deduper drops
                // slots whose state we already recorded
                GrandExchangeOffer[] offers = client.getGrandExchangeOffers();
                for (int slot = 0; offers != null && slot < offers.length; slot++)
                {
                    if (offers[slot] == null)
                    {
                        continue;
                    }
                    GrandExchangeOfferChanged current = new GrandExchangeOfferChanged();
                    current.setSlot(slot);
                    current.setOffer(offers[slot]);
                    processOfferEvent(current);
                }
            }

            // connect immediately instead of waiting for the next timer tick
            syncExecutor.execute(this::performSync);

            updatePanel();
            return true;
        });
    }

    @Override
    protected void shutDown()
    {
        overlayManager.remove(overlay);
        clientToolbar.removeNavigation(navButton);

        if (syncTask != null) syncTask.cancel(true);
        if (syncExecutor != null) syncExecutor.shutdownNow();

        saveState();

        log.info("OSRS GE Tracker stopped");
    }

    @Subscribe
    public void onGameStateChanged(GameStateChanged event)
    {
        if (event.getGameState() == GameState.LOGGED_IN)
        {
            initPlayerSession(false);
        }
        else if (event.getGameState() == GameState.LOGIN_SCREEN)
        {
            if (loggedIn)
            {
                saveState();
                loggedIn = false;
                playerName = null;
                slotOffers.clear();
                flipTracker.clear();
                deduper.clear();
            }
        }
    }

    @Subscribe
    public void onGrandExchangeOfferChanged(GrandExchangeOfferChanged event)
    {
        if (!loggedIn || playerName == null)
        {
            pendingEvents.add(event);
            return;
        }

        processOfferEvent(event);
    }

    private void processOfferEvent(GrandExchangeOfferChanged event)
    {
        GrandExchangeOffer offer = event.getOffer();
        int slot = event.getSlot();
        GrandExchangeOfferState state = offer.getState();

        if (state == GrandExchangeOfferState.EMPTY)
        {
            slotOffers.remove(slot);
            deduper.clearSlot(slot);
            return;
        }

        if (deduper.isDuplicate(slot, state, offer.getQuantitySold(), offer.getSpent()))
        {
            return;
        }

        String itemName = itemManager.getItemComposition(offer.getItemId()).getName();

        // carry the placement time across events for the same offer;
        // a new offer (different item or fresh slot) starts the clock now
        long now = System.currentTimeMillis();
        TradeOffer previous = slotOffers.get(slot);
        long placedTimestamp = (previous != null
            && previous.getItemId() == offer.getItemId()
            && previous.getPlacedTimestamp() > 0)
            ? previous.getPlacedTimestamp()
            : now;

        TradeOffer tradeOffer = TradeOffer.builder()
            .slot(slot)
            .itemId(offer.getItemId())
            .itemName(itemName)
            .price(offer.getPrice())
            .totalQuantity(offer.getTotalQuantity())
            .quantityFilled(offer.getQuantitySold())
            .amountSpent(offer.getSpent())
            .state(state)
            .isBuy(state == GrandExchangeOfferState.BUYING
                || state == GrandExchangeOfferState.BOUGHT
                || state == GrandExchangeOfferState.CANCELLED_BUY)
            .timestamp(now)
            .placedTimestamp(placedTimestamp)
            .build();

        slotOffers.put(slot, tradeOffer);

        // record every terminal outcome, including zero-fill cancels (fill-rate data)
        if (tradeOffer.isComplete())
        {
            allOutcomes.add(OfferOutcome.builder()
                .itemId(tradeOffer.getItemId())
                .itemName(itemName)
                .isBuy(tradeOffer.isBuy())
                .price(tradeOffer.getPrice())
                .totalQuantity(tradeOffer.getTotalQuantity())
                .quantityFilled(tradeOffer.getQuantityFilled())
                .placedTimestamp(tradeOffer.getPlacedTimestamp())
                .endedTimestamp(tradeOffer.getTimestamp())
                .cancelled(state == GrandExchangeOfferState.CANCELLED_BUY
                    || state == GrandExchangeOfferState.CANCELLED_SELL)
                .synced(false)
                .build());
        }

        if ((state == GrandExchangeOfferState.BOUGHT || state == GrandExchangeOfferState.CANCELLED_BUY)
            && tradeOffer.getQuantityFilled() > 0)
        {
            // buys start at offer placement, not observed fill — offers that
            // fill while logged out keep their true hold time
            flipTracker.recordBuy(tradeOffer.getItemId(), tradeOffer.getQuantityFilled(),
                tradeOffer.getAveragePrice(), tradeOffer.getPlacedTimestamp());
            sessionStats.recordBuy();
            log.debug("Buy completed: {} x{} @ {}", itemName,
                tradeOffer.getQuantityFilled(), tradeOffer.getAveragePrice());
        }

        if ((state == GrandExchangeOfferState.SOLD || state == GrandExchangeOfferState.CANCELLED_SELL)
            && tradeOffer.getQuantityFilled() > 0)
        {
            sessionStats.recordSell();
            CompletedTrade trade = flipTracker.matchSell(tradeOffer.getItemId(), itemName,
                tradeOffer.getQuantityFilled(), tradeOffer.getAveragePrice(), tradeOffer.getTimestamp());

            if (trade != null)
            {
                allTrades.add(trade);
                sessionStats.recordFlip(trade);
                log.info("Flip completed: {} x{} profit={} (tax={})",
                    itemName, trade.getQuantity(), trade.getProfit(), trade.getTax());
            }
        }

        updatePanel();
        saveState();
    }

    @Subscribe
    public void onConfigChanged(ConfigChanged event)
    {
        if (!"osrsge-tracker".equals(event.getGroup())) return;

        if ("apiKey".equals(event.getKey()))
        {
            apiClient.setApiKey(config.apiKey());
        }
        if ("syncBaseUrl".equals(event.getKey()))
        {
            apiClient.setBaseUrl(config.syncBaseUrl());
        }
        if ("syncIntervalSeconds".equals(event.getKey()) || "syncEnabled".equals(event.getKey()))
        {
            startSyncTask();
        }
        // immediate feedback when sync settings change
        if ("apiKey".equals(event.getKey()) || "syncBaseUrl".equals(event.getKey())
            || "syncEnabled".equals(event.getKey()))
        {
            syncExecutor.execute(this::performSync);
        }
    }

    private void startSyncTask()
    {
        if (syncTask != null) syncTask.cancel(false);

        if (!config.syncEnabled()) return;

        // short initial delay so the panel shows Synced quickly after login/config
        syncTask = syncExecutor.scheduleAtFixedRate(this::performSync,
            2,
            config.syncIntervalSeconds(),
            TimeUnit.SECONDS);
    }

    private void performSync()
    {
        if (playerName == null || !config.syncEnabled()) return;

        try
        {
            // Sync unsynced trades from the in-memory list (the source of truth);
            // marking the same objects synced keeps the flag across saveState overwrites
            List<CompletedTrade> unsynced = allTrades.stream()
                .filter(t -> !t.isSynced())
                .collect(Collectors.toList());
            if (!unsynced.isEmpty())
            {
                apiClient.syncTrades(unsynced).thenAccept(success -> {
                    if (success)
                    {
                        syncConnected = true;
                        unsynced.forEach(t -> t.setSynced(true));
                        saveState();
                        log.info("Synced {} trades", unsynced.size());
                    }
                    else
                    {
                        syncConnected = false;
                    }
                    updatePanel();
                });
            }

            List<OfferOutcome> unsyncedOutcomes = allOutcomes.stream()
                .filter(o -> !o.isSynced())
                .collect(Collectors.toList());
            if (!unsyncedOutcomes.isEmpty())
            {
                apiClient.syncOutcomes(unsyncedOutcomes).thenAccept(success -> {
                    if (success)
                    {
                        unsyncedOutcomes.forEach(o -> o.setSynced(true));
                        saveState();
                    }
                });
            }

            // Always send the offers snapshot: empty list clears stale server
            // rows and doubles as a connection heartbeat for the Synced label
            apiClient.syncActiveOffers(getActiveOffers()).thenAccept(success -> {
                syncConnected = success;
                updatePanel();
            });
        }
        catch (Exception e)
        {
            syncConnected = false;
            log.error("Sync error", e);
        }
    }

    public List<TradeOffer> getActiveOffers()
    {
        return slotOffers.values().stream()
            .filter(TradeOffer::isActive)
            .collect(Collectors.toList());
    }

    public void resetSession()
    {
        sessionStats = new SessionStats();
        updatePanel();
    }

    private void saveState()
    {
        if (playerName == null) return;
        tradeStorage.saveTrades(playerName, allTrades);
        tradeStorage.saveOutcomes(playerName, allOutcomes);
        tradeStorage.saveLedger(playerName, flipTracker.snapshot());

        List<TradeOffer> offers = new ArrayList<>(slotOffers.values());
        tradeStorage.saveOffers(playerName, offers);
    }

    private void updatePanel()
    {
        if (panel != null)
        {
            SwingUtilities.invokeLater(() -> {
                panel.updateStats();
                panel.updateActiveOffers(getActiveOffers());
                panel.updateTradeHistory(allTrades);
            });
        }
    }
}

